import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> dict with side, price, qty, time, active

    for time, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, stime, sid = sell_heap[0]
                if sid not in book or not book[sid]['active']:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                trade_qty = min(remaining, book[sid]['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] == 0:
                    book[sid]['active'] = False
                    heapq.heappop(sell_heap)
                else:
                    # partial fill stays at front, but since qty changed,
                    # we can't just leave it in heap incorrectly ordered
                    # (price/time unchanged, so heap order is still valid)
                    break if remaining == 0 else None
            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': time, 'active': True}
                heapq.heappush(buy_heap, (-price, time, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, btime, bid = buy_heap[0]
                bp = -bp_neg
                if bid not in book or not book[bid]['active']:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                trade_qty = min(remaining, book[bid]['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] == 0:
                    book[bid]['active'] = False
                    heapq.heappop(buy_heap)
                else:
                    break if remaining == 0 else None
            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': time, 'active': True}
                heapq.heappush(sell_heap, (price, time, oid))

    return trades

